#!/usr/bin/env python3
# VENDORED, NOT WRITTEN HERE. Do not edit this file in this repository.
#   source   krateo-blueprints/openstack-ironic-operator-kog  hack/resync-cadence.py
#   ref      main (fetched 2026-11-28; NOT the PR branch)
#   commit   124f8dfd5428becb8963c2f1263ab8d3b9a4f508  (last upstream commit touching this file)
# Changes belong UPSTREAM: fix it there and re-vendor, so the two copies stay one
# tool. Used here (a) as a CLI for the denominators and the configured resync, and
# (b) imported by hack/nova-create-window.py for its log parsing. With ONE CR it
# VOIDs on cadence by its own rule (< 3 full passes); that is expected, not a gate.
"""Did rest-dynamic-controller's resync actually fire every `resyncInterval`?  OFFLINE: reads a log.

    kubectl logs deploy/<rdc> | hack/resync-cadence.py
    hack/resync-cadence.py rdc.log          (`-` or no argument reads stdin)

This tool never spawns anything, never touches a cluster and never writes a file. It reads a
rest-dynamic-controller JSON log and prints:

  * the CONFIGURED resync interval, READ from the controller's own startup line
    (`"msg":"Starting."` ... `"resyncInterval":180000000000`, nanoseconds) with the `build`
    string beside it. If that line is not in the log window the configured value is UNKNOWN,
    never assumed;
  * the ACHIEVED pass-to-pass cadence, on the controller's ENQUEUE clock, printed as a PAIR
    with their ratio and a loud DIVERGENT marker past --divergence (default 1.1);
  * per full pass, `enqueue -> first line` (queue latency) and `first line -> last line`
    (drain smear), because that is what contention actually costs.

HOW A PASS IS IDENTIFIED. Every pass line carries `queuedAt`: the moment the controller
ENQUEUED that work item. A pass is the set of lines whose `queuedAt` values CLUSTER (items of
one pass are within about a millisecond of each other; --tolerance, default 1s, chains
neighbours). A pass is FULL when it spans >= --min-crs DISTINCT CRs (default 8). A cluster of
exactly one CR is an event-driven pass; 2..min-crs-1 CRs is a PARTIAL pass. Neither is ever
mixed into a cadence, latency or smear number: a statistic over a mixed population is an
error of its own, so they are only counted.

THE HISTORY, which is the reason this tool exists. The same question was answered wrongly
four times in one afternoon and each failure looked like a different bug:

  v1  a pass = "a burst of >=8 log lines" (lines grouped by >5s of silence). Under load a pass
      SPLITS: one arrived as bursts of 5 and 4 lines, so neither fragment met the threshold
      and the pass went unrecognised. A split pass fails a count test on both halves.
  v2  group bursts within 60s, require >=8 lines in the group. Still a line COUNT over a time
      WINDOW, i.e. still a proxy, and it breaks again on a pass smeared past the window.
  v3  group on the exact `queuedAt` string. `queuedAt` is stamped PER ITEM at nanosecond
      resolution, so that is one group per line: 286 "passes" of one CR each.
  v4  cluster on the ENQUEUE clock with a small tolerance, count DISTINCT CRs. Correct.

Every version before v4 measured the tick by its CONSEQUENCES (lines appearing) instead of the
controller's own record of it. And the wrong versions produced a wrong CONCLUSION, not an
error: v1/v2 reported a 360.1s pass-to-pass gap and "a tick was dropped" was published. On the
enqueue clock all 32 intervals were 180.0s and no pass was ever dropped: the pass fired on
time and its workers were starved (enqueue->first-line 23.84s, drain smear 15.8s). That
retraction had to be sent to a peer who had already changed their harness on it. So this tool
reports cadence and starvation as SEPARATE numbers, and a starved-but-on-time run is NOT
DIVERGENT.

DROPPED-PASS CANDIDATES are intervals >= --candidate-factor (default 1.5) x the median. They
are candidates, not findings: a long interval on the enqueue clock is the only thing that
could be a dropped tick, and it still needs a second look. They do not change the exit code.

VOID BEFORE PASS. Fewer than 3 full passes (a cadence from two passes is one interval) or no
startup line means the cadence cannot be concluded. The verdict line says so FIRST, and no
ratio or cadence statistic is printed for a VOID run.

EXIT CODES  0 OK (measured; not divergent)   1 DIVERGENT   2 VOID (could not measure)
            64 usage error (EX_USAGE; argparse's own 2 is remapped, as in
            watch-condition-flap.py, so a typo never reads as a VOID).

`--self-test` runs offline against fixtures written in this file, including each case named
for the history above. `--json` prints the same result machine-readably.
"""
import argparse
import calendar
import json
import os
import re
import statistics
import subprocess
import time
import sys
import tempfile

EXIT_OK, EXIT_DIVERGENT, EXIT_VOID = 0, 1, 2
EXIT_USAGE = 64  # EX_USAGE, sysexits.h; never reuse 2 (VOID)
MIN_FULL_PASSES = 3
NS = 1_000_000_000

DEFAULT_TOLERANCE_S = 1.0
DEFAULT_MIN_CRS = 8
DEFAULT_DIVERGENCE = 1.1
DEFAULT_CANDIDATE_FACTOR = 1.5


class UsageExitParser(argparse.ArgumentParser):
    """argparse, except every usage error exits EXIT_USAGE instead of 2 (VOID)."""

    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(EXIT_USAGE, "%s: error: %s\n" % (self.prog, message))


# ---------------------------------------------------------------- parsing
_TS = re.compile(r"^(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d):(\d\d)(?:\.(\d+))?(Z|[+-]\d\d:\d\d)$")


def parse_ts_ns(s):
    """RFC3339 -> integer ns since the epoch, or None. Any fraction width (`.1Z` .. `.123456789Z`)."""
    if not isinstance(s, str):
        return None
    m = _TS.match(s)
    if not m:
        return None
    y, mo, d, h, mi, se = (int(m.group(i)) for i in range(1, 7))
    frac = (m.group(7) or "")[:9].ljust(9, "0")
    try:
        sec = calendar.timegm((y, mo, d, h, mi, se, 0, 0, 0))
    except (ValueError, OverflowError):
        return None
    off = m.group(8)
    if off != "Z":
        sign = 1 if off[0] == "+" else -1
        sec -= sign * (int(off[1:3]) * 3600 + int(off[4:6]) * 60)
    return sec * NS + int(frac)


def fmt_ns(ns):
    sec, frac = divmod(ns, NS)
    t = time.gmtime(sec)
    return "%04d-%02d-%02dT%02d:%02d:%02d.%09dZ" % (t.tm_year, t.tm_mon, t.tm_mday, t.tm_hour,
                                                    t.tm_min, t.tm_sec, frac)


def read_records(text):
    """-> (records, counts). records: dicts that parsed as JSON objects."""
    recs = []
    total = unparsed = 0
    for line in text.splitlines():
        if not line.strip():
            continue
        total += 1
        try:
            obj = json.loads(line)
        except ValueError:
            unparsed += 1
            continue
        if not isinstance(obj, dict):
            unparsed += 1
            continue
        recs.append(obj)
    return recs, {"total_lines": total, "unparsed_lines": unparsed}


def startup_info(recs):
    """The controller's own startup lines. -> list of {build, resync_s, ...}."""
    out = []
    for r in recs:
        if r.get("msg") == "Starting." and isinstance(r.get("resyncInterval"), (int, float)) \
                and not isinstance(r.get("resyncInterval"), bool):
            out.append({"build": r.get("build"), "resync_s": r["resyncInterval"] / NS,
                        "timestamp": r.get("timestamp")})
    return out


# ---------------------------------------------------------------- analysis
def cr_key(r):
    return (r.get("kind"), r.get("namespace"), r.get("name"))


def cluster_on_enqueue(items, tol_ns):
    """items: [(queued_ns, record)]. Chain neighbours whose queuedAt gap is <= tol_ns."""
    items = sorted(items, key=lambda it: it[0])
    clusters, cur, prev = [], [], None
    for q, r in items:
        if prev is not None and q - prev > tol_ns:  # MUTATION-SITE: cluster
            clusters.append(cur)
            cur = []
        cur.append((q, r))
        prev = q
    if cur:
        clusters.append(cur)
    return clusters


def stats(xs):
    if not xs:
        return None
    return {"min": min(xs), "median": statistics.median(xs), "max": max(xs), "n": len(xs)}


def analyze(text, tolerance_s=DEFAULT_TOLERANCE_S, min_crs=DEFAULT_MIN_CRS,
            divergence=DEFAULT_DIVERGENCE, candidate_factor=DEFAULT_CANDIDATE_FACTOR):
    recs, counts = read_records(text)
    starts = startup_info(recs)
    items, no_q, bad_q = [], 0, 0
    for r in recs:
        if "queuedAt" not in r:
            no_q += 1
            continue
        q = parse_ts_ns(r.get("queuedAt"))
        if q is None:
            bad_q += 1
            continue
        items.append((q, r))

    clusters = cluster_on_enqueue(items, int(tolerance_s * NS))
    full, single, partial = [], 0, 0
    for c in clusters:
        n = len({cr_key(r) for _, r in c})
        if n >= min_crs:  # MUTATION-SITE: full
            full.append(c)
        elif n == 1:
            single += 1
        else:
            partial += 1

    passes = []
    for c in full:
        enq = c[0][0]
        ts = [t for t in (parse_ts_ns(r.get("timestamp")) for _, r in c) if t is not None]
        lat = (min(ts) - enq) / NS if ts else None
        smear = (max(ts) - min(ts)) / NS if ts else None
        passes.append({"enqueue": fmt_ns(enq), "enqueue_ns": enq,
                       "crs": len({cr_key(r) for _, r in c}), "lines": len(c),
                       "enqueue_to_first_line_s": lat, "first_to_last_line_s": smear})
    intervals = [(passes[i + 1]["enqueue_ns"] - passes[i]["enqueue_ns"]) / NS
                 for i in range(len(passes) - 1)]

    # the configured value: the LAST startup line (a restart replaces the earlier one)
    configured = starts[-1] if starts else None
    void = []
    if configured is None:
        void.append("no startup line (`\"msg\":\"Starting.\"` with resyncInterval) in this log window: "
                    "the configured resync interval is UNKNOWN, so achieved cadence has nothing to be "
                    "compared with")
    if len(passes) < MIN_FULL_PASSES:
        void.append("%d full pass(es) (>=%d distinct CRs on one enqueue cluster); need >=%d. A cadence "
                    "from %d pass(es) is %d interval(s), not a cadence"
                    % (len(passes), min_crs, MIN_FULL_PASSES, len(passes), max(len(passes) - 1, 0)))

    res = {
        "verdict": None, "exit": None, "void_reasons": void,
        "params": {"tolerance_s": tolerance_s, "min_crs": min_crs, "divergence": divergence,
                   "candidate_factor": candidate_factor},
        "configured": ({"resync_s": configured["resync_s"], "build": configured["build"],
                        "startup_lines": len(starts),
                        "resync_values_differ": len({s["resync_s"] for s in starts}) > 1}
                       if configured else {"resync_s": None, "build": None, "startup_lines": 0,
                                           "state": "UNKNOWN"}),
        "counts": {"total_lines": counts["total_lines"], "unparsed_lines": counts["unparsed_lines"],
                   "lines_without_queuedAt": no_q, "lines_with_unparseable_queuedAt": bad_q,
                   "lines_with_queuedAt": len(items), "full_passes": len(passes),
                   "single_cr_passes": single, "partial_passes": partial},
        "intervals_s": intervals, "passes": passes,
        "achieved": None, "ratio": None, "divergent": None, "dropped_candidates": [],
        "queue_latency_s": None, "drain_smear_s": None,
    }
    for p in passes:
        del p["enqueue_ns"]

    if void:
        res["verdict"], res["exit"] = "VOID", EXIT_VOID
        return res

    ach = stats(intervals)
    res["achieved"] = ach
    cfg = configured["resync_s"]
    res["ratio"] = ach["median"] / cfg if cfg else None
    if res["ratio"] is None:
        res["verdict"], res["exit"] = "VOID", EXIT_VOID
        res["void_reasons"].append("configured resyncInterval is 0: no ratio exists")
        res["achieved"] = None
        return res
    r = res["ratio"]
    res["divergent"] = bool(r > divergence or r < 1.0 / divergence)  # MUTATION-SITE: divergent
    res["dropped_candidates"] = [{"after_pass_index": i, "interval_s": v, "x_median": v / ach["median"]}
                                 for i, v in enumerate(intervals) if v >= candidate_factor * ach["median"]]
    res["queue_latency_s"] = stats([p["enqueue_to_first_line_s"] for p in passes
                                    if p["enqueue_to_first_line_s"] is not None])
    res["drain_smear_s"] = stats([p["first_to_last_line_s"] for p in passes
                                  if p["first_to_last_line_s"] is not None])
    res["verdict"] = "DIVERGENT" if res["divergent"] else "OK"
    res["exit"] = EXIT_DIVERGENT if res["divergent"] else EXIT_OK
    return res


# ---------------------------------------------------------------- rendering
def _st(s):
    return "n/a" if not s else "min %.2fs  median %.2fs  max %.2fs  (n=%d)" % (
        s["min"], s["median"], s["max"], s["n"])


def render(res, source):
    L = ["resync-cadence: %s" % source]
    if res["verdict"] == "VOID":
        L.append("VERDICT VOID  -- cadence NOT concluded:")
        for v in res["void_reasons"]:
            L.append("  - " + v)
    cfg = res["configured"]
    if cfg["resync_s"] is None:
        L.append("configured: UNKNOWN (no startup line in this window)")
    else:
        extra = ""
        if cfg["startup_lines"] > 1:
            extra = "  [%d startup lines; using the last%s]" % (
                cfg["startup_lines"], "; VALUES DIFFER" if cfg["resync_values_differ"] else "")
        L.append("configured: %.1fs  build %s%s" % (cfg["resync_s"], cfg["build"], extra))
    c = res["counts"]
    L.append("lines: total %d, unparsed %d, without queuedAt %d, bad queuedAt %d, with queuedAt %d"
             % (c["total_lines"], c["unparsed_lines"], c["lines_without_queuedAt"],
                c["lines_with_unparseable_queuedAt"], c["lines_with_queuedAt"]))
    L.append("passes (enqueue clusters, tolerance %gs): full %d (>=%d distinct CRs), single-CR %d "
             "(event-driven, excluded from every statistic), partial %d (excluded)"
             % (res["params"]["tolerance_s"], c["full_passes"], res["params"]["min_crs"],
                c["single_cr_passes"], c["partial_passes"]))
    if res["intervals_s"]:
        L.append("pass-to-pass intervals, enqueue clock: " + ", ".join("%.1f" % v for v in res["intervals_s"]))
    if res["verdict"] == "VOID":
        return "\n".join(L)
    a = res["achieved"]
    L.append("intervals: median %.1fs  min %.1fs  max %.1fs  (n=%d)" % (a["median"], a["min"], a["max"], a["n"]))
    L.append("configured %.1fs vs achieved %.1fs  ratio %.3f%s" % (
        cfg["resync_s"], a["median"], res["ratio"],
        "   *** DIVERGENT *** (threshold %gx either way)" % res["params"]["divergence"]
        if res["divergent"] else "   (within %gx)" % res["params"]["divergence"]))
    if res["dropped_candidates"]:
        for d in res["dropped_candidates"]:
            L.append("dropped-pass CANDIDATE: interval #%d is %.1fs = %.2fx median (candidate, not a finding)"
                     % (d["after_pass_index"], d["interval_s"], d["x_median"]))
    else:
        L.append("dropped-pass candidates: none (no interval >= %gx median)" % res["params"]["candidate_factor"])
    L.append("enqueue -> first line (queue latency): " + _st(res["queue_latency_s"]))
    L.append("first line -> last line (drain smear):  " + _st(res["drain_smear_s"]))
    L.append("VERDICT %s" % res["verdict"])
    return "\n".join(L)


def public(res):
    return res


# ---------------------------------------------------------------- self-test
def build_log(passes, startup=True, resync_s=180, extra=(), build="0.98.0-0333829", ncr=10):
    """passes: list of dicts {at, crs, latency, smear, fragments(optional: list of (n_lines, extra_delay))}.

    `at` is the enqueue time in seconds from a fixed origin. Each item's queuedAt differs from its
    neighbours by tens of microseconds (distinct nanosecond strings, as the controller stamps them)."""
    origin = parse_ts_ns("2026-11-28T18:00:00Z")
    lines = []
    if startup:
        lines.append(json.dumps({"msg": "Starting.", "build": build, "resyncInterval": resync_s * NS,
                                 "maxErrorRetryInterval": 90 * NS, "workers": 5,
                                 "timestamp": "2026-11-28T17:59:50.0Z"}))
    lines.append(json.dumps({"msg": "no queuedAt here", "timestamp": "2026-11-28T17:59:51.0Z"}))
    events = []
    for p in passes:
        n = p["crs"]
        for i in range(n):
            q = origin + int(p["at"] * NS) + i * 37_113  # 37.113us apart: every string distinct
            if "fragments" in p:  # (count, extra seconds) per fragment, in order
                acc, t_off = 0, 0.0
                for cnt, delay in p["fragments"]:
                    if i < acc + cnt:
                        t_off = delay
                        break
                    acc += cnt
                else:
                    t_off = p["fragments"][-1][1]
                ts = q + int((p["latency"] + t_off) * NS)
            else:
                frac = i / (n - 1) if n > 1 else 0
                ts = q + int((p["latency"] + p["smear"] * frac) * NS)
            events.append((ts, {"msg": "External resource is up to date", "kind": "BaremetalNode",
                                "apiVersion": "baremetal.ogen.krateo.io/v1-0-0", "name": "blade%02d" % i,
                                "namespace": "openstack", "queuedAt": fmt_ns(q), "event": "observe",
                                "timestamp": fmt_ns(ts)}))
    for ts, r in sorted(events, key=lambda e: e[0]):
        lines.append(json.dumps(r))
    lines.extend(extra)
    return "\n".join(lines) + "\n"


def self_test():
    total = passed = 0

    def check(name, cond):
        nonlocal total, passed
        total += 1
        if cond:
            passed += 1
        else:
            print("SELF-TEST FAIL: " + name)

    def series(n, step=180.0, **kw):
        return [dict(at=10 + i * step, crs=10, latency=kw.get("latency", 0.4),
                     smear=kw.get("smear", 0.5)) for i in range(n)]

    def single(at, name="solo"):
        return json.dumps({"msg": "External resource is up to date", "kind": "BaremetalNode",
                           "name": name, "namespace": "openstack", "queuedAt": fmt_ns(
                               parse_ts_ns("2026-11-28T18:00:00Z") + int(at * NS)),
                           "event": "observe", "timestamp": fmt_ns(
                               parse_ts_ns("2026-11-28T18:00:00Z") + int((at + 0.2) * NS))})

    near = lambda a, b, eps=0.01: a is not None and abs(a - b) <= eps
    # A broken analysis must produce FAIL lines, never a traceback that hides every later case.
    med = lambda st: st["median"] if st else None
    fmt = lambda v: "None" if v is None else "%.2f" % v

    # 1 quiet: negative control. Everything on time, nothing starved.
    r = analyze(build_log(series(6)))
    check("quiet: verdict OK (got %s)" % r["verdict"], r["verdict"] == "OK" and r["exit"] == EXIT_OK)
    check("quiet: not DIVERGENT", r["divergent"] is False)
    check("quiet: 6 full passes (got %d)" % r["counts"]["full_passes"], r["counts"]["full_passes"] == 6)
    check("quiet: all 5 intervals are 180.0s", len(r["intervals_s"]) == 5 and all(near(v, 180.0, 1e-6) for v in r["intervals_s"]))
    check("quiet: ratio 1.000", near(r["ratio"], 1.0, 1e-6))
    check("quiet: configured 180s read from the startup line, build beside it",
          r["configured"]["resync_s"] == 180.0 and r["configured"]["build"] == "0.98.0-0333829")
    check("quiet: no dropped candidates", r["dropped_candidates"] == [])
    check("quiet: queue latency small (median %s)" % fmt(med(r["queue_latency_s"])), near(med(r["queue_latency_s"]), 0.4, 0.01))
    check("quiet: drain smear small", near(med(r["drain_smear_s"]), 0.5, 0.01))
    txt = render(r, "t")
    check("quiet: text carries the pair and no DIVERGENT marker",
          "configured 180.0s vs achieved 180.0s" in txt and "*** DIVERGENT" not in txt)
    check("quiet: the 'without queuedAt' line (startup etc.) is counted", r["counts"]["lines_without_queuedAt"] == 2)
    check("quiet: total lines counted (1 startup + 1 no-q + 60)", r["counts"]["total_lines"] == 62)

    # 2 loaded: the retraction case. Enqueue clock on time; workers starved.
    r = analyze(build_log(series(6, latency=23.84, smear=15.8)))
    check("loaded: still NOT DIVERGENT on cadence (starved workers are not a slipped scheduler)",
          r["verdict"] == "OK" and r["divergent"] is False and all(near(v, 180.0, 1e-6) for v in r["intervals_s"]))
    check("loaded: queue latency shows the starvation (median %s)" % fmt(med(r["queue_latency_s"])), near(med(r["queue_latency_s"]), 23.84, 0.01))
    check("loaded: drain smear shows it (median %s)" % fmt(med(r["drain_smear_s"])), near(med(r["drain_smear_s"]), 15.8, 0.01))
    check("loaded: no dropped candidates", r["dropped_candidates"] == [])

    # 3 genuinely dropped pass: one 360s enqueue interval.
    pl = series(7)
    for p in pl[4:]:
        p["at"] += 180.0
    r = analyze(build_log(pl))
    check("dropped: a 360.0s interval is present", any(near(v, 360.0, 1e-6) for v in r["intervals_s"]))
    check("dropped: flagged as exactly one candidate (got %d)" % len(r["dropped_candidates"]), len(r["dropped_candidates"]) == 1)
    check("dropped: candidate is the 360s interval, ~2.0x median",
          r["dropped_candidates"] and near(r["dropped_candidates"][0]["interval_s"], 360.0, 1e-6)
          and near(r["dropped_candidates"][0]["x_median"], 2.0, 1e-6))
    check("dropped: the median stays 180 so cadence is not DIVERGENT, and the candidate does not change the exit",
          r["verdict"] == "OK" and r["exit"] == EXIT_OK)
    check("dropped: text says CANDIDATE, not 'dropped'", "CANDIDATE" in render(r, "t"))

    # 4 v1 regression: one pass split by smear into fragments of 5 and 4+ lines, 12s apart.
    pl = series(4)
    pl[1] = dict(at=190.0, crs=9, latency=0.4, smear=0, fragments=[(5, 0.0), (4, 12.0)])
    r = analyze(build_log(pl, ))
    check("v1 split pass: still ONE pass of 9 CRs, not two fragments (full %d)" % r["counts"]["full_passes"],
          r["counts"]["full_passes"] == 4 and len(r["passes"]) > 1 and r["passes"][1]["crs"] == 9 and r["passes"][1]["lines"] == 9)
    check("v1 split pass: nothing was classified as a fragment", r["counts"]["partial_passes"] == 0
          and r["counts"]["single_cr_passes"] == 0)
    check("v1 split pass: the smear shows the split (12.0s)", len(r["passes"]) > 1 and near(r["passes"][1]["first_to_last_line_s"], 12.0, 0.01))
    check("v1 split pass: its enqueue interval is still 180.0s, so no 'dropped tick'",
          r["dropped_candidates"] == [] and all(near(v, 180.0, 1e-6) for v in r["intervals_s"]))

    # 5 v3 regression: queuedAt strings all differ in nanoseconds within one pass.
    text = build_log(series(4))
    qs = {json.loads(l)["queuedAt"] for l in text.splitlines() if '"queuedAt"' in l}
    r = analyze(text)
    check("v3 ns jitter: the fixture really has one distinct queuedAt string per line (%d)" % len(qs), len(qs) == 40)
    check("v3 ns jitter: still 4 passes, not 40 (got %d full + %d single)" % (r["counts"]["full_passes"], r["counts"]["single_cr_passes"]),
          r["counts"]["full_passes"] == 4 and r["counts"]["single_cr_passes"] == 0)

    # 6 no startup line: configured UNKNOWN, VOID before any cadence claim.
    r = analyze(build_log(series(6), startup=False))
    check("no startup: VOID, exit 2", r["verdict"] == "VOID" and r["exit"] == EXIT_VOID)
    check("no startup: configured is UNKNOWN (None), never assumed", r["configured"]["resync_s"] is None)
    check("no startup: no ratio, no achieved, no divergence claim",
          r["ratio"] is None and r["achieved"] is None and r["divergent"] is None)
    txt = render(r, "t")
    check("no startup: VOID is stated BEFORE any cadence number (verdict at line 2)",
          txt.splitlines()[1].startswith("VERDICT VOID") and txt.find("VERDICT VOID") < txt.find("180.0"))
    check("no startup: text says UNKNOWN and prints no ratio", "UNKNOWN" in txt and "ratio" not in txt)

    # 7 two full passes: VOID even with a startup line.
    r = analyze(build_log(series(2)))
    check("2 passes: VOID, exit 2", r["verdict"] == "VOID" and r["exit"] == EXIT_VOID)
    check("2 passes: the reason names the pass count", any("2 full pass" in v for v in r["void_reasons"]))
    check("2 passes: no cadence statistic, no ratio", r["ratio"] is None and r["achieved"] is None
          and r["queue_latency_s"] is None)
    check("2 passes: exactly 3 passes is the smallest that measures", analyze(build_log(series(3)))["verdict"] == "OK")

    # 8 mixed populations: single-CR passes counted apart, never mixed into a statistic.
    solos = tuple(single(10 + i * 180 + 90 + 0.0, "solo%d" % i) for i in range(5))
    r = analyze(build_log(series(6), extra=solos))
    check("mixed: 6 full and 5 single-CR passes counted separately (got %d/%d)" % (r["counts"]["full_passes"], r["counts"]["single_cr_passes"]),
          r["counts"]["full_passes"] == 6 and r["counts"]["single_cr_passes"] == 5)
    check("mixed: the event-driven passes sit at the half-way points yet every interval is still 180.0s (not 90.0s)",
          len(r["intervals_s"]) == 5 and all(near(v, 180.0, 1e-6) for v in r["intervals_s"]))
    check("mixed: latency statistics cover the 6 full passes only", (r["queue_latency_s"] or {}).get("n") == 6 and (r["drain_smear_s"] or {}).get("n") == 6)
    check("mixed: verdict unaffected", r["verdict"] == "OK" and r["divergent"] is False)
    pl = series(6)
    pl.insert(2, dict(at=300.0, crs=3, latency=0.2, smear=0.1))
    r = analyze(build_log(pl))
    check("partial: a 3-CR cluster is PARTIAL, excluded from every statistic",
          r["counts"]["partial_passes"] == 1 and r["counts"]["full_passes"] == 6
          and all(near(v, 180.0, 1e-6) for v in r["intervals_s"]))
    check("min-crs flag: lowering it to 3 promotes that cluster to a full pass",
          analyze(build_log(pl), min_crs=3)["counts"]["full_passes"] == 7)

    # 9 DIVERGENT: positive control, and the threshold flag.
    r = analyze(build_log(series(6, step=270.0)))
    check("divergent: achieved 270s vs configured 180s is DIVERGENT, exit 1",
          r["verdict"] == "DIVERGENT" and r["exit"] == EXIT_DIVERGENT and near(r["ratio"], 1.5, 1e-6))
    check("divergent: the text carries the loud marker", "*** DIVERGENT ***" in render(r, "t"))
    r = analyze(build_log(series(6, step=90.0)))
    check("divergent: a TOO FAST cadence (90s vs 180s) is divergent as well", r["verdict"] == "DIVERGENT" and near(r["ratio"], 0.5, 1e-6))
    check("divergent: 190s (ratio 1.056) is inside the default 1.1 band",
          analyze(build_log(series(6, step=190.0)))["verdict"] == "OK")
    check("divergent: --divergence 1.02 makes the same 190s run DIVERGENT",
          analyze(build_log(series(6, step=190.0)), divergence=1.02)["verdict"] == "DIVERGENT")
    r = analyze(build_log(series(6, step=60.0), resync_s=60))
    check("configured is read, not assumed: a 60s resync with a 60s cadence is OK", r["verdict"] == "OK" and r["configured"]["resync_s"] == 60.0)

    # 10 parsing robustness.
    r = analyze(build_log(series(4), extra=("not json at all", "[1, 2]", json.dumps({"queuedAt": "garbage", "name": "x"}))))
    check("parse: unparsed and bad-queuedAt lines are counted, not fatal",
          r["counts"]["unparsed_lines"] == 2 and r["counts"]["lines_with_unparseable_queuedAt"] == 1 and r["verdict"] == "OK")
    check("parse: fractional widths and offsets", parse_ts_ns("2026-11-28T18:43:54.1Z") == parse_ts_ns("2026-11-28T18:43:54.100000000Z")
          and parse_ts_ns("2026-11-28T19:43:54+01:00") == parse_ts_ns("2026-11-28T18:43:54Z")
          and parse_ts_ns("nope") is None and parse_ts_ns(None) is None)
    check("parse: empty log is VOID", analyze("")["verdict"] == "VOID")
    check("parse: an empty log still names both reasons", len(analyze("")["void_reasons"]) == 2)
    two = build_log(series(4)) + json.dumps({"msg": "Starting.", "build": "0.99.0-x", "resyncInterval": 90 * NS}) + "\n"
    r = analyze(two)
    check("parse: with two startup lines the LAST wins and the difference is flagged",
          r["configured"]["resync_s"] == 90.0 and r["configured"]["resync_values_differ"] is True
          and "VALUES DIFFER" in render(r, "t"))
    check("parse: the JSON form round-trips", json.loads(json.dumps(analyze(build_log(series(4)))))["verdict"] == "OK")

    # 11 CLI: exit codes, file and stdin input, --json. communicate(input=) handles stdin itself
    # (Python 3.9 flushes a closed stdin and raises ValueError if it is closed by hand first).
    me = os.path.abspath(__file__)

    def cli(*args, stdin=None):
        p = subprocess.run([sys.executable, "-I", me] + list(args), input=stdin,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True, timeout=60)
        return p.returncode, p.stdout, p.stderr

    with tempfile.TemporaryDirectory() as tmp:
        good, bad, void = (os.path.join(tmp, n) for n in ("good.log", "div.log", "void.log"))
        for path, txt in ((good, build_log(series(5))), (bad, build_log(series(5, step=270.0))),
                          (void, build_log(series(2)))):
            with open(path, "w") as f:
                f.write(txt)
        rc, out, _ = cli(good)
        check("CLI: a clean file exits 0 (got %d)" % rc, rc == 0 and "VERDICT OK" in out)
        rc, out, _ = cli(bad)
        check("CLI: a divergent file exits 1 (got %d)" % rc, rc == 1 and "*** DIVERGENT ***" in out)
        rc, out, _ = cli(void)
        check("CLI: a VOID file exits 2, not 0 and not 1 (got %d)" % rc, rc == 2 and "VERDICT VOID" in out)
        rc, out, _ = cli("-", stdin=build_log(series(5)))
        check("CLI: stdin via `-` exits 0 (got %d)" % rc, rc == 0)
        rc, out, _ = cli(stdin=build_log(series(5, step=270.0)))
        check("CLI: stdin with no argument reads the log (got %d)" % rc, rc == 1)
        rc, out, _ = cli("--json", bad)
        j = json.loads(out) if out.strip().startswith("{") else {}
        check("CLI: --json emits one JSON document with the verdict and the pair",
              rc == 1 and j.get("verdict") == "DIVERGENT" and j.get("configured", {}).get("resync_s") == 180.0
              and near(j.get("ratio"), 1.5, 1e-6) and "intervals_s" in j and "counts" in j)
        rc, out, _ = cli("--json", void)
        j = json.loads(out)
        check("CLI: --json on a VOID run says VOID, with the reasons and no ratio",
              rc == 2 and j["verdict"] == "VOID" and j["ratio"] is None and j["void_reasons"])
        rc, out, _ = cli("--divergence", "1.6", bad)
        check("CLI: --divergence is honoured (1.5x under a 1.6 threshold exits 0, got %d)" % rc, rc == 0)
        rc, out, _ = cli("--min-crs", "11", good)
        check("CLI: --min-crs 11 leaves no full pass in a 10-CR log, so VOID (got %d)" % rc, rc == 2)
        rc, out, _ = cli("--tolerance", "0", good)
        check("CLI: --tolerance 0 is the v3 grouping and cannot find a pass in a jittered log (got %d)" % rc, rc == 2)
        rc, out, err = cli("--no-such-flag")
        check("CLI: an unknown flag exits 64, distinct from VOID's 2 (got %d)" % rc, rc == EXIT_USAGE and "usage" in err.lower())
        rc, out, err = cli(os.path.join(tmp, "missing.log"))
        check("CLI: a missing file exits 64 (got %d)" % rc, rc == EXIT_USAGE and "missing.log" in err)
        rc, out, err = cli("--min-crs", "0", good)
        check("CLI: --min-crs 0 is a usage error (got %d)" % rc, rc == EXIT_USAGE)
        rc, out, err = cli("--tolerance", "-1", good)
        check("CLI: a negative tolerance is a usage error (got %d)" % rc, rc == EXIT_USAGE)
        rc, out, err = cli("--divergence", "0.9", good)
        check("CLI: --divergence below 1 is a usage error (got %d)" % rc, rc == EXIT_USAGE)
        rc, out, err = cli("--help")
        check("CLI: --help exits 0 and documents 64", rc == 0 and "64" in out)
        rc, out, err = cli("--self-test", "--bogus")
        check("CLI: a bad flag beside --self-test is still a usage error (got %d)" % rc, rc == EXIT_USAGE)

    # 12 the instrument never spawns or writes: proved from the source, outside this function.
    src = open(me).read()
    prod = src.split("# ---------------------------------------------------------------- self-test")[0]
    spawns = re.compile(r"Popen|subprocess\.|os\.system|open\([^)]*['\"][wa]")
    scrub = prod.replace("import subprocess", "")
    check("static: nothing before the self-test section spawns a process or opens a file for writing",
          not spawns.search(scrub))
    check("static control: the same screen DOES fire on a spawn, a write-open and an os.system",
          all(spawns.search(x) for x in ("subprocess.run(['kubectl'])", "open('f', 'w')", "os.system('x')")))

    print("SELF-TEST: %d/%d assertions passed" % (passed, total))
    return 0 if passed == total else 1


# ---------------------------------------------------------------- CLI
def build_parser():
    ap = UsageExitParser(
        allow_abbrev=False,
        description="Compare rest-dynamic-controller's configured resync interval with the cadence "
                    "its own enqueue clock shows. Offline: reads a log, spawns nothing.",
        epilog="Exit: 0 OK, 1 DIVERGENT, 2 VOID (could not measure), 64 usage error.")
    ap.add_argument("log", nargs="?", default="-", help="log file, or - / omitted for stdin")
    ap.add_argument("--self-test", "--selftest", action="store_true", dest="self_test",
                    help="run the offline self-test and exit")
    ap.add_argument("--json", action="store_true", help="machine-readable output")
    ap.add_argument("--tolerance", type=float, default=DEFAULT_TOLERANCE_S, metavar="SECONDS",
                    help="queuedAt gap that still counts as the same pass (default %(default)s)")
    ap.add_argument("--min-crs", type=int, default=DEFAULT_MIN_CRS, metavar="N",
                    help="distinct CRs for a FULL pass (default %(default)s)")
    ap.add_argument("--divergence", type=float, default=DEFAULT_DIVERGENCE, metavar="X",
                    help="DIVERGENT when achieved/configured is >X or <1/X (default %(default)s)")
    ap.add_argument("--candidate-factor", type=float, default=DEFAULT_CANDIDATE_FACTOR, metavar="X",
                    help="intervals >= X times the median are dropped-pass candidates (default %(default)s)")
    return ap


def main(argv=None):
    ap = build_parser()
    a = ap.parse_args(argv)
    if a.self_test:
        return self_test()
    if a.tolerance < 0:
        ap.error("--tolerance must be >= 0")
    if a.min_crs < 1:
        ap.error("--min-crs must be >= 1")
    if a.divergence < 1:
        ap.error("--divergence must be >= 1")
    if a.candidate_factor <= 1:
        ap.error("--candidate-factor must be > 1")
    if a.log == "-":
        text, source = sys.stdin.read(), "<stdin>"
    else:
        try:
            with open(a.log, encoding="utf-8", errors="replace") as f:
                text = f.read()
        except OSError as e:
            ap.error("cannot read %s: %s" % (a.log, e.strerror or e))
        source = a.log
    res = analyze(text, a.tolerance, a.min_crs, a.divergence, a.candidate_factor)
    if a.json:
        print(json.dumps(public(res), indent=2, sort_keys=True))
    else:
        print(render(res, source))
    return res["exit"]


if __name__ == "__main__":
    sys.exit(main())
